INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Babette Guldsmeden');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Bredgade 78, Indre By, Copenhagen, Hovedstaden, 1260, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '98');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at Babette Guldsmeden, you''ll be centrally located in Copenhagen, within a 5-minute drive of Tivoli Gardens and Strøget. This spa hotel is 0.7 mi (1.1 km) from Nyhavn and 1.6 mi (2.6 km) from City Hall Square.</p><p>Take time to pamper yourself with a visit to the full-service spa. Additional features at this hotel include complimentary wireless internet access, concierge services, and a banquet hall.</p><p>Satisfy your appetite at Skagen Fiskerestaurant, a seafood restaurant which features a bar/lounge. Dining is also available at the coffee shop/cafe. Buffet breakfasts are served on weekdays from 6:30 AM to 10:30 AM and on weekends from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and luggage storage. This hotel has 2 meeting rooms available for events.</p><p>Stay in one of 98 guestrooms featuring LCD televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Private bathrooms have designer toiletries and hair dryers. Conveniences include electric kettles, and housekeeping is provided daily.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '6022449');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '9a640ef1-0203-1e4c-558d-7196ea43c879', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '9a640ef1-0203-1e4c-558d-7196ea43c879', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p><p>The host or staff will greet you upon arrival</p><p>If you plan to arrive after 23:00 on your check-in day, contact the property in advance by email/phone</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '12a30eca-11b9-c1d1-414e-d1436581aab4', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '12a30eca-11b9-c1d1-414e-d1436581aab4', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '760cd911-318b-e6b7-2fce-9e6934c92c40', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '760cd911-318b-e6b7-2fce-9e6934c92c40', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, extra beds cannot be added. Crib policies vary according to room type. Please refer to the relevant room type policy.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'df67b48f-e598-0f4c-91a8-10fa7cb2f221', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'df67b48f-e598-0f4c-91a8-10fa7cb2f221', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Fri] 06:30-10:30 Open [Sat - Sun] 07:00-11:00 Open</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–12 years old</td><td>DKK 125 (approx. $19.00) per person</td></tr><tr><td>Children 13–17 years old</td><td>DKK 245 (approx. $37.25) per person</td></tr><tr><td>Adult</td><td>DKK 245 (approx. $37.25) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c3efae47-20eb-b802-b4e8-cd8b3338a8cb', 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c3efae47-20eb-b802-b4e8-cd8b3338a8cb', 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of DKK 500 (approx. $76.02) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment on the day of check-out.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c5f85c70-22f1-2e16-d50b-58f9f939098e', 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c5f85c70-22f1-2e16-d50b-58f9f939098e', 'POLICY', 'pet', 'en', 'policy_content', '<p>Pets are allowed on request</p><p>Types of pets allowed: dogs</p><p>Fee: DKK 250 (approx. $38.01) per pet per stay</p>');
