INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Babette Guldsmeden');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Bredgade 78, Indre By, 1260 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '98');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Babette Guldsmeden ở trung tâm Copenhagen, cách Công viên Tivoli và Phố Strøget 5 phút lái xe. Khách sạn spa này cách Khu Nyhavn 1,1 km và cách Quảng trường Tòa thị chính 2,6 km.</p><p>Hãy dành cho mình thời gian tận hưởng sự chăm sóc thật đặc biệt tại khu spa phục vụ đầy đủ các liệu pháp. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và phòng đại tiệc.</p><p>Thưởng thức những bữa ăn ngon tại nhà hàng hải sản Skagen Fiskerestaurant có quầy bar/khu lounge. Hoặc khách cũng có thể chọn dùng bữa tại quán cà phê. Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 10:30 và cuối tuần (phụ phí) từ 7:00 đến 11:00.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và dịch vụ trông giữ/bảo quản hành lý. Khách sạn này có 2 phòng họp để phục vụ các chương trình hội thảo, sự kiện.</p><p>Hãy nghỉ tại một trong 98 phòng được trang bị TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng có đồ dùng nhà tắm được thiết kế riêng và máy sấy tóc. Phòng được trang bị ấm điện; và dịch vụ dọn phòng phục vụ hàng ngày.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'b8f70a52-bd84-0c68-3cf4-08cafae64b91', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '6022449');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '9a640ef1-0203-1e4c-558d-7196ea43c879', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '9a640ef1-0203-1e4c-558d-7196ea43c879', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Chủ nhà hoặc nhân viên sẽ đón tiếp bạn khi bạn đến nơi</p><p>Nếu bạn dự định sẽ đến sau 23:00 vào ngày nhận phòng, vui lòng liên hệ trước với cơ sở lưu trú qua email/điện thoại</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '12a30eca-11b9-c1d1-414e-d1436581aab4', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '12a30eca-11b9-c1d1-414e-d1436581aab4', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '760cd911-318b-e6b7-2fce-9e6934c92c40', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, '760cd911-318b-e6b7-2fce-9e6934c92c40', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'df67b48f-e598-0f4c-91a8-10fa7cb2f221', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'df67b48f-e598-0f4c-91a8-10fa7cb2f221', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:30 Đang Mở [Thứ 7 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 3 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 4–12 tuổi</td><td>125 DKK(khoảng 493.800₫) mỗi người</td></tr><tr><td>Trẻ em 13–17 tuổi</td><td>245 DKK(khoảng 967.847₫) mỗi người</td></tr><tr><td>Người lớn</td><td>245 DKK(khoảng 967.847₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c3efae47-20eb-b802-b4e8-cd8b3338a8cb', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c3efae47-20eb-b802-b4e8-cd8b3338a8cb', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 500 DKK (khoảng 1.975.199₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744817, 'c5f85c70-22f1-2e16-d50b-58f9f939098e', 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
