INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'f8efa714-ec22-aea7-3d24-e995a70f9766', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Hotel Mayfair');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'f8efa714-ec22-aea7-3d24-e995a70f9766', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Colbjørnsensgade 8, Vesterbro/Kongens Enghave, Copenhagen, Hovedstaden, 1652, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'f8efa714-ec22-aea7-3d24-e995a70f9766', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'f8efa714-ec22-aea7-3d24-e995a70f9766', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '198');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'f8efa714-ec22-aea7-3d24-e995a70f9766', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Hotel Mayfair is a boutique lifestyle hotel in central Copenhagen, just steps from Copenhagen Central Station and Tivoli Gardens. Located in the vibrant Vesterbro district, the hotel offers easy access to the city’s main attractions, shopping streets, restaurants, and cultural landmarks.</p><p>Combining Scandinavian design with a relaxed urban atmosphere, Hotel Mayfair features comfortable rooms and modern facilities, making it an ideal base for both leisure and business travelers visiting Copenhagen. With its central location and welcoming surroundings, the hotel provides a convenient and stylish starting point for exploring the city.</p><p>Hotel Mayfair is a boutique lifestyle hotel in central Copenhagen, just steps from Copenhagen Central Station and Tivoli Gardens. Located in the vibrant Vesterbro district, the hotel offers easy access to the city’s main attractions, shopping streets, restaurants, and cultural landmarks.</p><p>Combining Scandinavian design with a relaxed urban atmosphere, Hotel Mayfair features comfortable rooms and modern facilities, making it an ideal base for both leisure and business travelers visiting Copenhagen. With its central location and welcoming surroundings, the hotel provides a convenient and stylish starting point for exploring the city.</p><p>Don''t miss out on recreational opportunities including a 24-hour fitness center and bicycles to rent.</p><p>Featured amenities include dry cleaning/laundry services at a charge, and a 24-hour front desk.</p><p>Stay in one of our guestrooms featuring flat-screen televisions. Complimentary wireless Internet access keeps you connected, and chrome cast is available so you can connect to your streaming devices. Bathrooms feature bathtubs or showers with rainfall showerheads and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'f8efa714-ec22-aea7-3d24-e995a70f9766', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '227259');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'd90e3559-28c5-4488-0e74-bb6015e90c3e', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'd90e3559-28c5-4488-0e74-bb6015e90c3e', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–24:00</strong></p><p>Check-out: <strong>00:00–11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '4f03ea8e-a2df-1f31-0421-d20cd6ff79ee', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '4f03ea8e-a2df-1f31-0421-d20cd6ff79ee', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '99448f64-72ad-2ebf-52b0-4d71b21323bf', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '99448f64-72ad-2ebf-52b0-4d71b21323bf', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, extra beds cannot be added. Crib policies vary according to room type. Please refer to the relevant room type policy.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '9f80a260-2850-930d-93b4-47e921d2cf53', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '9f80a260-2850-930d-93b4-47e921d2cf53', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>This property has 2 options for extra breakfasts.</p><p>Cuisine: Local cuisine</p><p>Opening hours: [Mon - Fri] 06:30-10:00 Open [Sat - Sun] 07:30-11:00 Open</p><table><tr><td>Children 4 years old and under</td><td>Free</td></tr><tr><td>Children 5–8 years old</td><td>DKK 95 (approx. $14.44) per person</td></tr><tr><td>Children 9–17 years old</td><td>DKK 225 (approx. $34.21) per person</td></tr><tr><td>Adult</td><td>DKK 225 (approx. $34.21) per person</td></tr></table><p>Cuisine: Western</p><p>Opening hours: [Mon - Fri] 06:30-10:00 Open [Sat - Sun] 07:30-11:00 Open</p><p>Price for extra breakfasts: Varies based on the food ordered</p><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'e390cb64-ed34-4cc2-3a8e-401d3a6ab3a9', 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, 'e390cb64-ed34-4cc2-3a8e-401d3a6ab3a9', 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of DKK 1,500 (approx. $228.05) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 7 days after check-out.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744865, '96a31409-1853-992b-746a-fa1342e60d42', 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
