INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Comfort Hotel Vesterbro, cách Công viên Tivoli và Quảng trường Tòa thị chính 10 phút đi bộ. Khách sạn cách Phố Strøget 1,7 km và cách Torvehallerne 1,9 km.</p><p>Đừng bỏ qua những dịch vụ, tiện nghi thể thao, giải trí tuyệt vời, bao gồm trung tâm thể dục và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và phòng đại tiệc.</p><p>Khách có thể thưởng thức nhiều món ăn ngon tại nhà hàng hoặc dùng bữa nhẹ ở quán cà phê của Khách sạn. Đập tan cơn khát với đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:30 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm nhận phòng nhanh, trả phòng nhanh và dịch vụ giặt ủi/giặt khô. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 72 mét vuông, bao gồm khu hội nghị và phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ tại một trong 400 phòng được trang bị TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình kỹ thuật số sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm được trang bị buồng tắm vòi sen và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '5bcb83dd-5e08-8040-a456-7fe6cc9e4f3f', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '232090');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '4ef3a4f1-26ab-1964-bc1f-80c889fca6f4', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '4ef3a4f1-26ab-1964-bc1f-80c889fca6f4', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p><p>Nếu bạn đến nơi ngoài khung giờ nhận phòng, hãy liên hệ trước với cơ sở lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '04e6a449-e65b-9c89-3495-5f200e3080b5', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '04e6a449-e65b-9c89-3495-5f200e3080b5', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '29667bdd-d9d9-bcf2-d66c-18703a157dd7', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '29667bdd-d9d9-bcf2-d66c-18703a157dd7', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '05fdd019-8890-514f-9b74-df43e29c7943', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '05fdd019-8890-514f-9b74-df43e29c7943', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:30-11:00 Đang Mở</p><table><tr><td>Người lớn</td><td>175 DKK(khoảng 691.320₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '50f4a1b1-d3f7-4245-acad-ed71c88edc78', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '50f4a1b1-d3f7-4245-acad-ed71c88edc78', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '5f40dbd5-0071-4888-2eb1-8c7fb8f474dc', 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, '5f40dbd5-0071-4888-2eb1-8c7fb8f474dc', 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Phí: 300 DKK (khoảng 1.185.119₫)/thú cưng/lần lưu trú</p>');
