INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (744866, 'ebcbb2aa-72f2-3306-6e6b-c30f75f97b0b', 'POLICY', 'serviceAnimal', 'vi', 'policy_content', '<p>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</p>');
