INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '20494e5a-9afe-d640-6670-f4bb422dfb0e', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'AC Hotel Bella Sky Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '20494e5a-9afe-d640-6670-f4bb422dfb0e', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Martha Christensens Vej 5, Amager Vest, Copenhagen, Hovedstaden, 2300, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '20494e5a-9afe-d640-6670-f4bb422dfb0e', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '20494e5a-9afe-d640-6670-f4bb422dfb0e', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '811');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '20494e5a-9afe-d640-6670-f4bb422dfb0e', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Experience 4-star sophistication in Denmark''s capital city with the beautifully designed accommodations and deluxe amenities at AC Hotel Bella Sky Copenhagen. Boasting a location near the airport and the vibrant city center, our pet-friendly hotel in Copenhagen is steps away from the train station, which allows for easy exploration of local attractions, including Tivoli Gardens and Amager Common. Unpack your bags in modern hotel rooms with pillow top bedding, floor-to-ceiling windows and authentic Danish design. Then explore our hotel''s luxurious amenities, including a fitness center and delicious restaurants. Start your day with the hot breakfast buffet and savor locally-sourced fare for lunch or dinner. If visiting Copenhagen for business, plan your next successful event in the adjacent Bella Center and tackle projects with our hotel''s complimentary Wi-Fi, parking and onsite business center. We are ready to make your visit memorable at our hotel in downtown Copenhagen.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '20494e5a-9afe-d640-6670-f4bb422dfb0e', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '1986559');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '66acda38-84ea-52ec-4fae-47f08c076a49', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '66acda38-84ea-52ec-4fae-47f08c076a49', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–24:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '7b4d9dde-30fa-0346-763e-4386a4373eba', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '7b4d9dde-30fa-0346-763e-4386a4373eba', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, 'c9107a6d-37b3-fa3f-b836-df7bba06d5ac', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, 'c9107a6d-37b3-fa3f-b836-df7bba06d5ac', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '676960ce-13b0-58b9-80d3-e1012859e81d', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '676960ce-13b0-58b9-80d3-e1012859e81d', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Continental</p><p>Opening hours: [Mon - Fri] 06:30-10:30 Open [Sat - Sun] 06:30-11:00 Open</p><table><tr><td>Children 3 years old and under</td><td>Free</td></tr><tr><td>Children 4–17 years old</td><td>DKK 125 (approx. $19.00) per person</td></tr><tr><td>Adult</td><td>DKK 195 (approx. $29.65) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '27f841b0-5cd3-d999-4f5e-6b0c1635a0cc', 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (1863116, '27f841b0-5cd3-d999-4f5e-6b0c1635a0cc', 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of DKK 250 (approx. $38.01) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment within 7 days after check-out.</strong></p>');
