INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Go Hotel Østerport');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Oslo Pl. 5, Indre By, Copenhagen, Hovedstaden, 2100, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '170');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Centrally located in Copenhagen, Go Hotel Østerport is within a 15-minute walk of Little Mermaid and Rosenborg Castle. This hotel is 0.9 mi (1.4 km) from Copenhagen Christmas Market and 0.9 mi (1.4 km) from Strøget.</p><p>Enjoy recreational amenities such as a fitness center and bicycles to rent. Additional amenities at this hotel include complimentary wireless internet access, a television in a common area, and tour/ticket assistance.</p><p>Satisfy your appetite at the hotel''s coffee shop/cafe, or stop in at the snack bar/deli. Wrap up your day with a drink at the bar/lounge. Buffet breakfasts are served on weekdays from 6:30 AM to 9:30 AM and on weekends from 7:00 AM to 10:30 AM for a fee. Children aged 5 and younger eat free breakfast.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and multilingual staff. Limited parking is available onsite.</p><p>Make yourself at home in one of the 170 guestrooms. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Bathrooms have showers and hair dryers. Conveniences include desks and electric kettles, and housekeeping is provided on request.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '206313');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '749fc5db-7476-47a3-14f4-403d5cbde0be', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '749fc5db-7476-47a3-14f4-403d5cbde0be', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>06:00–11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'e4122960-9e3b-4cbb-a145-2d8febb261c5', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'e4122960-9e3b-4cbb-a145-2d8febb261c5', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5e1876d9-1c51-4a78-594a-ca30913b07c9', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5e1876d9-1c51-4a78-594a-ca30913b07c9', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'ad6814d3-7b2c-79ac-d2c9-8e3a95a59292', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'ad6814d3-7b2c-79ac-d2c9-8e3a95a59292', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Fri] 06:30-09:30 Open [Sat - Sun] 07:00-10:30 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 129 (approx. $19.61) per person</td></tr><tr><td>Adult</td><td>DKK 129 (approx. $19.61) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5a1259cd-af00-f732-b078-32ce1ea1afdc', 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5a1259cd-af00-f732-b078-32ce1ea1afdc', 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>Deposit required</strong></p><p>Deposit Collection Methods: <strong>A fixed amount of DKK 1,500 (approx. $228.05) is charged.</strong></p><p>Deposit Payment Methods: <strong>This property accepts credit cards</strong></p><p>Deposit Refund: <strong>The deposit will be returned to the original account of payment on the day of check-out.</strong></p>');
