INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Go Hotel Østerport');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Oslo Pl. 5, Indre By, 2100 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '170');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Go Hotel Østerport cách Little Mermaid và Lâu đài Rosenborg 15 phút đi bộ. Khách sạn cách Chợ Giáng sinh Copenhagen 1,4 km và cách Phố Strøget 1,4 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí như trung tâm thể dục và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, TV ở khu vực chung và dịch vụ hỗ trợ tour/vé du lịch.</p><p>Khách có thể dùng bữa tại quán cà phê của Khách sạn hoặc ghé qua tiệm/cửa hàng đồ ăn nhanh để mua quà vặt và thức ăn nhẹ. Thư giãn sau một ngày dài bên cạnh ly đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet các ngày trong tuần từ 6:30 đến 9:30 và cuối tuần (phụ phí) từ 7:00 đến 10:30. LOCALIZE</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm dịch vụ giặt ủi/giặt khô, quầy tiếp tân phục vụ 24 giờ/ngày và nhân viên thông thạo nhiều ngôn ngữ. Có số chỗ đậu xe có hạn trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 170 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm được trang bị buồng tắm vòi sen và máy sấy tóc. Tiện nghi phòng bao gồm bàn và ấm điện; bên cạnh đó dịch vụ dọn phòng cũng phục vụ dịch vụ dọn phòng (theo yêu cầu).</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '8f78089b-b878-ce83-deb7-488ffc87de1d', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '206313');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '749fc5db-7476-47a3-14f4-403d5cbde0be', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '749fc5db-7476-47a3-14f4-403d5cbde0be', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>06:00–11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'e4122960-9e3b-4cbb-a145-2d8febb261c5', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'e4122960-9e3b-4cbb-a145-2d8febb261c5', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5e1876d9-1c51-4a78-594a-ca30913b07c9', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5e1876d9-1c51-4a78-594a-ca30913b07c9', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'ad6814d3-7b2c-79ac-d2c9-8e3a95a59292', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, 'ad6814d3-7b2c-79ac-d2c9-8e3a95a59292', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-09:30 Đang Mở [Thứ 7 - CN] 07:00-10:30 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>129 DKK(khoảng 509.601₫) mỗi người</td></tr><tr><td>Người lớn</td><td>129 DKK(khoảng 509.601₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5a1259cd-af00-f732-b078-32ce1ea1afdc', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '5a1259cd-af00-f732-b078-32ce1ea1afdc', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 1.500 DKK (khoảng 5.925.596₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '907fb9ba-c817-e4f7-9fcc-ca41a3a90761', 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '907fb9ba-c817-e4f7-9fcc-ca41a3a90761', 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 275 DKK (khoảng 1.086.359₫)/thú cưng/lần lưu trú</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '77b408e1-3ba5-97dc-0c2d-f9b36aae1db1', 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2141126, '77b408e1-3ba5-97dc-0c2d-f9b36aae1db1', 'POLICY', 'serviceAnimal', 'vi', 'policy_content', '<p>Được phép mang theo động vật hỗ trợ nếu có yêu cầu</p>');
