INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '4e09f423-5163-c16e-08cd-ed800e04342b', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Copenhagen Marriott Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '4e09f423-5163-c16e-08cd-ed800e04342b', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Kalvebod Brygge 5, Indre By, 1560 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '4e09f423-5163-c16e-08cd-ed800e04342b', 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '4e09f423-5163-c16e-08cd-ed800e04342b', 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '406');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '4e09f423-5163-c16e-08cd-ed800e04342b', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Tọa lạc tại trung tâm Copenhagen, Copenhagen Marriott Hotel cách Bảo tàng Quốc gia Đan Mạch và Công viên Tivoli 15 phút đi bộ. Khách sạn sang trọng này cách Cung điện Christiansborg 0,8 km và cách Quảng trường Tòa thị chính 1,1 km.</p><p>Hãy tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm phòng tắm hơi, trung tâm thể dục phục vụ 24 giờ và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và cửa hàng quà tặng/sạp báo.</p><p>Khách có thể dùng bữa tại quầy bar/khu lounge nhìn ra bãi biển Copenhagen Pier Bar hoặc nghỉ lại phòng và thưởng thức những bữa ăn ngon với dịch vụ phòng 24 giờ. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 10:30 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng phục vụ 24 giờ, dịch vụ xe limo/xe đưa đón hạng sang và nhận phòng nhanh. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 887 mét vuông, bao gồm trung tâm hội nghị và phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ tại một trong 406 phòng được trang bị TV LCD. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Phòng tắm riêng với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '4e09f423-5163-c16e-08cd-ed800e04342b', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '229409');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '5e53cfde-5566-0c58-b5aa-3fc0dbd9c379', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '5e53cfde-5566-0c58-b5aa-3fc0dbd9c379', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 16:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, 'bb758f5f-5d3c-5c5d-694f-c4fa72bf03c5', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, 'bb758f5f-5d3c-5c5d-694f-c4fa72bf03c5', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, 'f4892dbc-739f-db63-f6ae-7fd6cb86294a', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, 'f4892dbc-739f-db63-f6ae-7fd6cb86294a', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '02b5469b-ba3b-960c-0e55-773276df96ec', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '02b5469b-ba3b-960c-0e55-773276df96ec', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 06:30-10:30 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>275 DKK(khoảng 1.086.359₫) mỗi người</td></tr><tr><td>Người lớn</td><td>275 DKK(khoảng 1.086.359₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '57cc810f-4b44-ece4-39de-4f83fa26a67e', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '57cc810f-4b44-ece4-39de-4f83fa26a67e', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khách sẽ thanh toán số tiền cọc cố định là 500 DKK (khoảng 1.975.199₫).</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Trong vòng 7 ngày sau ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '3f3223ca-05e4-1068-c72c-97e22d6472b5', 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2150756, '3f3223ca-05e4-1068-c72c-97e22d6472b5', 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 300 DKK (khoảng 1.185.119₫)/thú cưng/đêm</p>');
