INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', '71 Nyhavn Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Nyhavn 71, Indre By, Copenhagen, Hovedstaden, 1051, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '130');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at 71 Nyhavn Hotel, you''ll be centrally located in Copenhagen, steps from Nyhavn and 7 minutes by foot from Strøget. This luxury hotel is 1.6 mi (2.6 km) from Tivoli Gardens and 1.4 mi (2.2 km) from City Hall Square.</p><p>Take advantage of recreation opportunities such as bicycles to rent, or other amenities including complimentary wireless internet access and concierge services. Additional features at this hotel include babysitting (surcharge) and a television in a common area.</p><p>Enjoy a meal at Il MOLO, or stay in and take advantage of the hotel''s room service (during limited hours). Wrap up your day with a drink at the bar/lounge. A complimentary buffet breakfast is served on weekdays from 6:30 AM to 10:30 AM and on weekends from 7:00 AM to 11:00 AM.</p><p>Featured amenities include a business center, dry cleaning/laundry services, and a 24-hour front desk. Self parking (subject to charges) is available onsite.</p><p>Make yourself at home in one of the 130 air-conditioned rooms featuring minibars and flat-screen televisions. Complimentary wireless internet access keeps you connected, and cable programming is available for your entertainment. Bathrooms have designer toiletries and hair dryers. Conveniences include phones, as well as safes and desks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '207305');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'b4609153-d9ec-77f5-7409-4e5d64d9e55d', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'b4609153-d9ec-77f5-7409-4e5d64d9e55d', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '317c8ac7-2891-f811-9888-8107c4e7a467', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '317c8ac7-2891-f811-9888-8107c4e7a467', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'e12ab850-50cc-5234-2b31-d57faa1fc7ae', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'e12ab850-50cc-5234-2b31-d57faa1fc7ae', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, extra beds cannot be added. Crib policies vary according to room type. Please refer to the relevant room type policy.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '0e53ef6f-837f-1554-9aa1-403bb90c4b69', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '0e53ef6f-837f-1554-9aa1-403bb90c4b69', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Fri] 06:30-10:30 Open [Sat - Sun] 07:00-11:00 Open</p><table><tr><td>Children 2 years old and under</td><td>Free</td></tr><tr><td>Children 3–11 years old</td><td>DKK 135 (approx. $20.52) per person</td></tr><tr><td>Children 12–17 years old</td><td>DKK 269 (approx. $40.90) per person</td></tr><tr><td>Adult</td><td>DKK 269 (approx. $40.90) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'd194ecf6-f0f8-fecd-af8f-ea6fc8820bf3', 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
