INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', '71 Nyhavn Hotel');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Nyhavn 71, Indre By, 1051 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '130');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>71 Nyhavn Hotel tọa lạc ở trung tâm Copenhagen, chỉ cách Khu Nyhavn và Phố Strøget 7 phút đi bộ. Khách sạn sang trọng này cách Công viên Tivoli 2,6 km và cách Quảng trường Tòa thị chính 2,2 km.</p><p>Đừng bỏ qua cơ hội tận hưởng những dịch vụ thư giãn, giải trí như xe đạp cho thuê, hay những tiện nghi khác như quyền truy cập Internet không dây miễn phí và dịch vụ tư vấn/hỗ trợ khách. Khách sạn này còn có dịch vụ trông trẻ (phụ phí), cửa hàng quà tặng/sạp báo và TV ở khu vực chung.</p><p>Khách có thể lựa chọn dùng bữa tại nhà hàng của Khách sạn hoặc nghỉ lại trong phòng và thưởng thức những món ăn ngon với dịch vụ phòng (có giới hạn thời gian). Thư giãn sau một ngày dài bên cạnh ly đồ uống yêu thích tại quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet miễn phí vào các ngày trong tuần từ 6:30 đến 10:30 và từ 7:00 đến 11:00 cuối tuần.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng, dịch vụ giặt ủi/giặt khô và quầy tiếp tân phục vụ 24 giờ/ngày. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 130 phòng được trang bị máy điều hòa cùng minibar và TV màn hình phẳng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí; trong khi các chương trình truyền hình cáp sẽ mang đến những phút giây giải trí thoải mái. Các phòng tắm có đồ dùng nhà tắm được thiết kế riêng và máy sấy tóc. Tiện nghi phòng bao gồm điện thoại, cùng két bảo mật và bàn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '36cdb725-4783-c968-6c9d-ba7db7a1c515', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '207305');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'b4609153-d9ec-77f5-7409-4e5d64d9e55d', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'b4609153-d9ec-77f5-7409-4e5d64d9e55d', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '317c8ac7-2891-f811-9888-8107c4e7a467', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '317c8ac7-2891-f811-9888-8107c4e7a467', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'e12ab850-50cc-5234-2b31-d57faa1fc7ae', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'e12ab850-50cc-5234-2b31-d57faa1fc7ae', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung giường phụ. Chính sách về cũi khác nhau tùy theo loại phòng. Vui lòng tham khảo chính sách phòng liên quan.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '0e53ef6f-837f-1554-9aa1-403bb90c4b69', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, '0e53ef6f-837f-1554-9aa1-403bb90c4b69', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - Thứ 6] 06:30-10:30 Đang Mở [Thứ 7 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 2 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 3–11 tuổi</td><td>135 DKK(khoảng 533.304₫) mỗi người</td></tr><tr><td>Trẻ em 12–17 tuổi</td><td>269 DKK(khoảng 1.062.657₫) mỗi người</td></tr><tr><td>Người lớn</td><td>269 DKK(khoảng 1.062.657₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'd194ecf6-f0f8-fecd-af8f-ea6fc8820bf3', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'd194ecf6-f0f8-fecd-af8f-ea6fc8820bf3', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'd0051caa-771a-2c0f-0aa4-c5353aa977d7', 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159098, 'd0051caa-771a-2c0f-0aa4-c5353aa977d7', 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng nếu có yêu cầu</p><p>Loại thú cưng được phép mang theo: chó</p><p>Phí: 200 DKK (khoảng 790.079₫)/thú cưng/lần lưu trú</p>');
