INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Admiral Hotel Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'local_name', 'Admiral Hotel København');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Toldbodgade 24, 28, Indre By, 1253 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '366');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Admiral Hotel Copenhagen ở trung tâm Copenhagen, chỉ cách Khu Nyhavn và Phố Strøget 10 phút đi bộ. Khách sạn sang trọng này cách Công viên Tivoli 2,4 km và cách Quảng trường Tòa thị chính 2 km.</p><p>Hãy tận hưởng nhiều dịch vụ, tiện nghi thể thao, giải trí như phòng tắm hơi, trung tâm thể dục phục vụ 24 giờ và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Khách sạn này bao gồm quyền truy cập Internet không dây miễn phí, dịch vụ tư vấn/hỗ trợ khách và dịch vụ trông trẻ (phụ phí).</p><p>Thưởng thức món ăn kiểu Địa Trung Hải tại nhà hàng cao cấp aye aye có quầy bar/khu lounge hoặc nghỉ lại trong phòng và thưởng thức những bữa ăn ngon với dịch vụ phòng 24 giờ. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 6:30 đến 10:30 vào các ngày trong tuần.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm trung tâm dịch vụ văn phòng, báo miễn phí ở sảnh và dịch vụ giặt ủi/giặt khô. Có kế hoạch tổ chức sự kiện tại Copenhagen? Khách sạn này có khu vực tổ chức rộng 276 mét vuông, bao gồm trung tâm hội nghị và 11 phòng họp. Có bãi đậu xe tự phục vụ (phụ phí) trong khuôn viên.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 366 phòng được trang bị minibar và TV màn hình phẳng. Giường nệm có lớp đệm bông được trang bị bộ đồ giường cao cấp. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Phòng tắm riêng với bồn tắm hoặc buồng tắm vòi sen có đồ dùng nhà tắm miễn phí và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'adc40215-8cfc-4151-0f23-3e1b58be231a', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '229647');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'bd5f7c84-809f-a599-0d49-a5f811e43e10', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'bd5f7c84-809f-a599-0d49-a5f811e43e10', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>14:00 – 02:00 ngày hôm sau</strong></p><p>Trả phòng: <strong>Trước 12:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'dc36c050-c18b-fe45-7fbd-89277406dc7f', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'dc36c050-c18b-fe45-7fbd-89277406dc7f', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'de86ccb1-7fc3-ab02-4149-15bc1c01fb5e', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'de86ccb1-7fc3-ab02-4149-15bc1c01fb5e', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Chính sách giường phụ và cũi có thể thay đổi theo loại phòng. Vui lòng tham khảo chi tiết loại phòng để biết thêm thông tin.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, '104faa94-54e6-1221-107d-8f450819a8fb', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, '104faa94-54e6-1221-107d-8f450819a8fb', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 2 tuổi trở xuống</td><td>Miễn phí</td></tr><tr><td>Trẻ em 3–12 tuổi</td><td>130 DKK(khoảng 513.552₫) mỗi người</td></tr><tr><td>Trẻ em 13–17 tuổi</td><td>260 DKK(khoảng 1.027.103₫) mỗi người</td></tr><tr><td>Người lớn</td><td>260 DKK(khoảng 1.027.103₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, '4dcc2236-1221-6ce3-137e-44e6d4fd2cc5', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, '4dcc2236-1221-6ce3-137e-44e6d4fd2cc5', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Yêu cầu đặt cọc</strong></p><p>Hình thức thu tiền cọc: <strong>Khoản tiền cọc được tính dựa trên số lượng phòng bạn đặt. Mức phí là 1.000 DKK (khoảng 3.950.397₫)/phòng.</strong></p><p>Hình thức thanh toán tiền cọc: <strong>Cơ sở lưu trú này chấp nhận thẻ tín dụng và tiền mặt</strong></p><p>Hoàn tiền cọc: <strong>Tiền đặt cọc sẽ được hoàn lại vào tài khoản thanh toán ban đầu Vào ngày trả phòng.</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'fb36aba0-4cb5-28ad-b852-0ad55b6e3c53', 'POLICY', 'pet', 'vi', 'policy_title', 'Thú cưng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, 'fb36aba0-4cb5-28ad-b852-0ad55b6e3c53', 'POLICY', 'pet', 'vi', 'policy_content', '<p>Được phép mang theo thú cưng</p><p>Phí: Liên hệ với cơ sở lưu trú để biết chi tiết</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (2159295, '9f8aa8fa-887d-7ab3-8c47-241f169f179e', 'POLICY', 'serviceAnimal', 'vi', 'policy_title', 'Động vật hỗ trợ');
