INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'a&o Copenhagen Nørrebro');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'local_name', 'a&o Hostel København Nørrebro');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Tagensvej 135, 137, Norrebro, Copenhagen, Hovedstaden, 2200, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '167');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>With a stay at a&amp;o Copenhagen Norrebro - Hostel in Copenhagen (Nørrebro), you''ll be within a 10-minute drive of Nyhavn and Tivoli Gardens. This hostel is 2.6 mi (4.2 km) from City Hall Square and 2.6 mi (4.2 km) from Copenhagen Zoo.</p><p>Make use of convenient amenities such as complimentary wireless internet access, a television in a common area, and tour/ticket assistance. This hostel also features a vending machine and bike storage.</p><p>Grab a bite from the snack bar/deli serving guests of a&amp;o Copenhagen Norrebro - Hostel. Quench your thirst with your favorite drink at the bar/lounge. Buffet breakfasts are served on weekdays from 7:00 AM to 10:00 AM and on weekends from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include express check-out, a 24-hour front desk, and multilingual staff. Self parking (subject to charges) is available onsite.</p><p>Stay in one of 167 guestrooms featuring flat-screen televisions. Complimentary wireless internet access is available to keep you connected. Bathrooms have showers and hair dryers. Conveniences include blackout drapes/curtains, and housekeeping is provided daily.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5df2d7e1-66bc-f1dc-0771-ecdc0519649a', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '11954766');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '2eafb791-99c6-c0cc-a484-60ec7879f663', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '2eafb791-99c6-c0cc-a484-60ec7879f663', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 10:00</strong></p><p>Front desk hours: 24/7</p><p>Check in via app</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, 'f9f943f0-d438-1c28-4e3e-bf3770a3f28d', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, 'f9f943f0-d438-1c28-4e3e-bf3770a3f28d', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5571cf7c-356a-44bb-fb8e-880dc2bb7049', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '5571cf7c-356a-44bb-fb8e-880dc2bb7049', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>Extra bed and crib policies may vary according to room type. Please refer to the room type details for more information.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, 'ea13e5b8-06b1-b631-e6da-3bb41af55ab9', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, 'ea13e5b8-06b1-b631-e6da-3bb41af55ab9', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Cuisine: Continental, Gluten-free, Halal, Vegan, Vegetarian</p><p>Opening hours: [Sat - Sun] 07:00-11:00 Open [Mon - Fri] 07:00-10:00 Open</p><table><tr><td>Children 6 years old and under</td><td>Free</td></tr><tr><td>Children 7–17 years old</td><td>DKK 48.5 (approx. $7.37) per person</td></tr><tr><td>Adult</td><td>DKK 97 (approx. $14.75) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '580dd488-0e77-a247-2d93-fc5c9b8e262e', 'POLICY', 'deposit', 'en', 'policy_title', 'Deposit Policy');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '580dd488-0e77-a247-2d93-fc5c9b8e262e', 'POLICY', 'deposit', 'en', 'policy_content', '<p>Deposit: <strong>No deposit required by the property</strong></p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '44b7f1b4-3066-87e2-267c-d740e6dd0142', 'POLICY', 'pet', 'en', 'policy_title', 'Pets');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (7021883, '44b7f1b4-3066-87e2-267c-d740e6dd0142', 'POLICY', 'pet', 'en', 'policy_content', '<p>Pets are allowed on request</p><p>Types of pets allowed: dogs</p><p>Fee: DKK 115 (approx. $17.48) per pet per day</p>');
