INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, '77107ee8-b31e-e814-c189-e3fd76aaccf8', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'NH Collection Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, '77107ee8-b31e-e814-c189-e3fd76aaccf8', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Strandgade 7, Indre By, Copenhagen, Hovedstaden, 1401, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, '77107ee8-b31e-e814-c189-e3fd76aaccf8', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, '77107ee8-b31e-e814-c189-e3fd76aaccf8', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '394');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, '77107ee8-b31e-e814-c189-e3fd76aaccf8', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>Located in Copenhagen (Copenhagen City Centre), NH Collection Copenhagen is within a 15-minute walk of Nyhavn and Strøget. This luxury hotel is 1.1 mi (1.8 km) from Tivoli Gardens and 0.9 mi (1.4 km) from City Hall Square.</p><p>Enjoy recreational amenities such as a fitness center and bicycles to rent. Additional features at this hotel include complimentary wireless internet access, a banquet hall, and bike storage.</p><p>Enjoy local cuisine at Plates, one of the hotel''s many dining establishments, which include 2 restaurants and a coffee shop/cafe. Need to unwind? Take a break with a tasty beverage at one of the 2 bars/lounges. Buffet breakfasts are served on weekdays from 6:30 AM to 10:00 AM for a fee.</p><p>Featured amenities include dry cleaning/laundry services, a 24-hour front desk, and multilingual staff.</p><p>Make yourself at home in one of the 394 guestrooms featuring minibars and flat-screen televisions. Satellite television is provided for your entertainment. Private bathrooms with showers feature rainfall showerheads and hair dryers. Conveniences include phones, as well as safes and desks.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, '77107ee8-b31e-e814-c189-e3fd76aaccf8', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '23438123');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, 'd811cec0-f6a4-15f6-4aee-907ef39cc1ae', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (76325348, 'd811cec0-f6a4-15f6-4aee-907ef39cc1ae', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>15:00–24:00</strong></p><p>Check-out: <strong>Before 12:00</strong></p><p>Front desk hours: 24/7</p>');
