INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_name', 'Next House Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'en', 'hotel_address', 'Bernstorffsgade 27, Indre By, Copenhagen, Hovedstaden, 1577, Denmark');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'en', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'en', 'room_count', '433');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'en', 'description', '<p>A stay at Next House Copenhagen - Hostel places you in the heart of Copenhagen, within a 15-minute walk of Tivoli Gardens and City Hall Square. This hostel is 0.6 mi (1 km) from Strøget and 1.4 mi (2.2 km) from Nyhavn.</p><p>Be sure to enjoy recreational amenities including a fitness center and bicycles to rent. Additional features at this hostel include complimentary wireless internet access, an arcade/game room, and a fireplace in the lobby.</p><p>You can enjoy a meal at Next EATERY serving the guests of Next House Copenhagen - Hostel, or stop in at the snack bar/deli. Need to unwind? Take a break with a tasty beverage at one of the 4 bars/lounges. Buffet breakfasts are available daily from 7:00 AM to 11:00 AM for a fee.</p><p>Featured amenities include express check-in, express check-out, and a 24-hour front desk.</p><p>Make yourself at home in one of the 433 guestrooms. Complimentary wireless internet access is available to keep you connected. Bathrooms have showers and hair dryers.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'en', 'tripAdvisorId', '23984102');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '5fad0da6-dca0-dbd7-186b-3af140529af3', 'POLICY', 'checkInAndOut', 'en', 'policy_title', 'Check-in and Check-out Times');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '5fad0da6-dca0-dbd7-186b-3af140529af3', 'POLICY', 'checkInAndOut', 'en', 'policy_content', '<p>Check-in: <strong>After 15:00</strong></p><p>Check-out: <strong>Before 11:00</strong></p><p>Front desk hours: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '7eb9526d-d29f-2d6a-7a1a-ee904f79ab13', 'POLICY', 'childPolicy', 'en', 'policy_title', 'Child policies');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '7eb9526d-d29f-2d6a-7a1a-ee904f79ab13', 'POLICY', 'childPolicy', 'en', 'policy_content', '<p>Children of all ages are welcome at this property.</p><p>Additional fees may be charged for children using existing beds. Add the number of children to get a more accurate price.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, 'bdb5d724-80b6-5ed0-d800-5907cc6d25ae', 'POLICY', 'cribAndExtraBed', 'en', 'policy_title', 'Cribs and Extra Beds');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, 'bdb5d724-80b6-5ed0-d800-5907cc6d25ae', 'POLICY', 'cribAndExtraBed', 'en', 'policy_content', '<p>For all room types, cribs and extra beds cannot be added.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '53fc808e-48e9-73fa-ca9d-1369a7d4c354', 'POLICY', 'breakfast', 'en', 'policy_title', 'Breakfast');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '53fc808e-48e9-73fa-ca9d-1369a7d4c354', 'POLICY', 'breakfast', 'en', 'policy_content', '<p>Option: Buffet</p><p>Opening hours: [Mon - Sun] 07:00-11:00 Open</p><table><tr><td>Children 17 years old and under</td><td>DKK 69 (approx. $10.49) per person</td></tr><tr><td>Adult</td><td>DKK 69 (approx. $10.49) per person</td></tr></table><p>Contact the property to see if extra breakfast is available. If so, you can pay for it at the property.</p>');
