INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_name', 'Next House Copenhagen');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'vi', 'hotel_address', 'Bernstorffsgade 27, Indre By, 1577 Copenhagen, Hovedstaden, Đan Mạch');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'vi', 'countryCode', 'DK');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'vi', 'room_count', '433');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'vi', 'description', '<p>Next House Copenhagen - Hostel ở trung tâm Copenhagen, chỉ cách Công viên Tivoli và Quảng trường Tòa thị chính 15 phút đi bộ. Hostel này cách Phố Strøget 1 km và cách Khu Nyhavn 2,2 km.</p><p>Hãy nhớ đừng bỏ qua cơ hội tận hưởng mọi dịch vụ, tiện nghi thể thao, giải trí, bao gồm trung tâm thể dục và xe đạp cho thuê. Các dịch vụ, tiện ích khác tại Hostel này bao gồm quyền truy cập Internet không dây miễn phí, phòng trò chơi và lò sưởi ở sảnh.</p><p>Khách có thể dùng bữa tại Next EATERY ở Next House Copenhagen - Hostel hoặc ghé qua tiệm/cửa hàng đồ ăn nhanh để mua quà vặt và món ăn nhẹ. Đập tan cơn khát với đồ uống yêu thích của mình tại 4 quầy bar/khu lounge. Khách có thể dùng bữa sáng buffet (có phụ phí) từ 7:00 đến 11:00 hàng ngày.</p><p>Có nhiều dịch vụ, tiện ích dành cho khách, bao gồm nhận phòng nhanh, trả phòng nhanh và quầy tiếp tân phục vụ 24 giờ/ngày.</p><p>Hãy nghỉ ngơi thoải mái như đang ở nhà mình tại một trong 433 phòng. Bạn luôn có thể giữ liên lạc bằng kết nối internet không dây miễn phí ngay tại phòng. Các phòng tắm được trang bị buồng tắm vòi sen và máy sấy tóc.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '0a55f55e-c7d6-9b48-40c8-28e0648c2a1b', 'DESCRIPTION', 'hotelInfo', 'vi', 'tripAdvisorId', '23984102');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '5fad0da6-dca0-dbd7-186b-3af140529af3', 'POLICY', 'checkInAndOut', 'vi', 'policy_title', 'Thời gian nhận và trả phòng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '5fad0da6-dca0-dbd7-186b-3af140529af3', 'POLICY', 'checkInAndOut', 'vi', 'policy_content', '<p>Nhận phòng: <strong>Sau 15:00</strong></p><p>Trả phòng: <strong>Trước 11:00</strong></p><p>Giờ làm việc của quầy lễ tân: 24/7</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '7eb9526d-d29f-2d6a-7a1a-ee904f79ab13', 'POLICY', 'childPolicy', 'vi', 'policy_title', 'Chính sách cho trẻ em');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '7eb9526d-d29f-2d6a-7a1a-ee904f79ab13', 'POLICY', 'childPolicy', 'vi', 'policy_content', '<p>Trẻ em thuộc mọi độ tuổi đều được chào đón tại cơ sở lưu trú này.</p><p>Bạn có thể mất thêm phí để trẻ em sử dụng giường có sẵn. Hãy thêm số lượng trẻ em đi cùng để nhận được mức giá chính xác hơn.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, 'bdb5d724-80b6-5ed0-d800-5907cc6d25ae', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_title', 'Nôi/cũi và giường phụ');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, 'bdb5d724-80b6-5ed0-d800-5907cc6d25ae', 'POLICY', 'cribAndExtraBed', 'vi', 'policy_content', '<p>Mọi loại phòng đều không thể bổ sung cũi và giường phụ.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '53fc808e-48e9-73fa-ca9d-1369a7d4c354', 'POLICY', 'breakfast', 'vi', 'policy_title', 'Bữa sáng');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '53fc808e-48e9-73fa-ca9d-1369a7d4c354', 'POLICY', 'breakfast', 'vi', 'policy_content', '<p>Lựa chọn: Tự chọn</p><p>Giờ mở cửa: [Thứ 2 - CN] 07:00-11:00 Đang Mở</p><table><tr><td>Trẻ em 17 tuổi trở xuống</td><td>69 DKK(khoảng 272.577₫) mỗi người</td></tr><tr><td>Người lớn</td><td>69 DKK(khoảng 272.577₫) mỗi người</td></tr></table><p>Vui lòng liên hệ với cơ sở lưu trú để kiểm tra xem họ có dịch vụ thêm bữa sáng không. Nếu có, bạn có thể thanh toán cho dịch vụ này tại cơ sở lưu trú.</p>');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '84e191d5-28cf-c440-8ad5-fdf4edd04c58', 'POLICY', 'deposit', 'vi', 'policy_title', 'Chính sách đặt cọc');
INSERT INTO splatform_meta.trip_tmp_property_translation (property_id, row_uuid, type, section_type, lang, field, value) VALUES (83194466, '84e191d5-28cf-c440-8ad5-fdf4edd04c58', 'POLICY', 'deposit', 'vi', 'policy_content', '<p>Đặt cọc: <strong>Chỗ nghỉ không yêu cầu đặt cọc</strong></p>');
